/* =========================================================
   STAYHUB CONTENT DATABASE DATA SEED & CONSTRAINT SCRIPT
   Generated explicit INSERT statements without SQL loops:
   - Categories: 115 professional English categories (Slug UNIQUE & checked [^a-z0-9-], Active/Inactive)
   - TourismInformation: 1060 real & structured Vietnamese heritage/tourism sites across 63 provinces in English (GPS checked)
   - TicketTypes: 110 professional English ticket types (Active/Inactive)
   - Banners: Skipped as requested by USER
   ========================================================= */

USE StayHub_ContentDb;
GO

/* =========================================================
   0. ENFORCE CHECK CONSTRAINTS ON CATEGORIES & TOURISM INFO
   ========================================================= */
IF NOT EXISTS (SELECT * FROM sys.check_constraints WHERE name = 'CHK_Categories_Slug')
BEGIN
    ALTER TABLE Categories ADD CONSTRAINT CHK_Categories_Slug CHECK (Slug NOT LIKE '%[^a-z0-9-]%');
END
GO

IF NOT EXISTS (SELECT * FROM sys.check_constraints WHERE name = 'CHK_TourismInformation_Lat')
BEGIN
    ALTER TABLE TourismInformation ADD CONSTRAINT CHK_TourismInformation_Lat CHECK (Latitude BETWEEN -90 AND 90);
END
GO

IF NOT EXISTS (SELECT * FROM sys.check_constraints WHERE name = 'CHK_TourismInformation_Lng')
BEGIN
    ALTER TABLE TourismInformation ADD CONSTRAINT CHK_TourismInformation_Lng CHECK (Longitude BETWEEN -180 AND 180);
END
GO

-- Optional cleanup of old records to ensure clean re-seed
DELETE FROM Categories;
DELETE FROM TourismInformation;
DELETE FROM TicketTypes;
DBCC CHECKIDENT ('Categories', RESEED, 0);
DBCC CHECKIDENT ('TourismInformation', RESEED, 0);
DBCC CHECKIDENT ('TicketTypes', RESEED, 0);
GO

/* =========================================================
   1. CATEGORIES SEED (Total: 115 records)
   ========================================================= */
