INSERT INTO Categories (Id, Name, Slug, IconUrl, Description, IsActive) VALUES
(1, N'Island & Beach Resort Holidays', 'island-and-beach-resort-holidays', 'https://picsum.photos/seed/cat_icon_1/100/100', N'Explore pristine white-sand beaches, crystal-clear tropical waters, and experience world-class luxury stays at premium beachfront resorts.', 1),
(2, N'Eco-Tourism & Nature Exploration', 'eco-tourism-and-nature-exploration', 'https://picsum.photos/seed/cat_icon_2/100/100', N'Immerse yourself in lush national parks, biodiverse wildlife sanctuaries, and serene nature trails away from bustling city life.', 1),
