(1045, N'Traditional Noodle & Broth Specialties of Gia Lai', 'LocalFood', N'Iconic regional noodle soup of Gia Lai featuring rich bone broth simmered for hours, fresh rice noodles, and local aromatic herbs.', N'Central Wet Markets and Food Streets, Gia Lai', N'Gia Lai', N'Vietnam', 14.0058, 107.9775, 'https://picsum.photos/seed/tourism_site_1045/600/400', N'Gia Lai Culinary Heritage Association', 'https://stayhub.vn/di-san/1045', 'Active', GETDATE(), GETDATE()),
(1046, N'Traditional Banana-Leaf Wrapped Rice Cakes of Gia Lai', 'LocalFood', N'Rustic sticky rice cakes stuffed with savory mung bean and pork fillings, meticulously folded in fresh banana leaves across Gia Lai.', N'Artisan Craft Village, Nghia Tru Ward, Gia Lai', N'Gia Lai', N'Vietnam', 14.0313, 108.012, 'https://picsum.photos/seed/tourism_site_1046/600/400', N'Gia Lai Artisan Village Cooperative', 'https://stayhub.vn/di-san/1046', 'Active', GETDATE(), GETDATE()),
(1047, N'Charcoal-Grilled Meat & Mountain Spices of Gia Lai', 'LocalFood', N'Prime meat skewers marinated with indigenous mountain pepper and wild herbs, grilled over glowing charcoal briquettes in Gia Lai.', N'Night Food Market Quarter, Downtown Gia Lai', N'Gia Lai', N'Vietnam', 14.0568, 108.0465, 'https://picsum.photos/seed/tourism_site_1047/600/400', N'Gia Lai Gastronomy Center', 'https://stayhub.vn/di-san/1047', 'Active', GETDATE(), GETDATE()),
(1048, N'Regional River Hotpot & Seasonal Specialties of Gia Lai', 'LocalFood', N'Steaming aromatic hotpot combining sweet river seafood and unique wild mountain vegetables harvested from local rivers in Gia Lai.', N'Breezy Riverfront Dining District, Gia Lai', N'Gia Lai', N'Vietnam', 13.9323, 107.931, 'https://picsum.photos/seed/tourism_site_1048/600/400', N'Gia Lai Culinary Board', 'https://stayhub.vn/di-san/1048', 'Active', GETDATE(), GETDATE()),
(1049, N'Heritage Garden & Fine Dining Restaurant of Gia Lai', 'Restaurant', N'Refined dining venue set within historic colonial architecture, serving authentic regional heirloom recipes prepared by veteran chefs of Gia Lai.', N'88 Quang Trung Street, Downtown Gia Lai', N'Gia Lai', N'Vietnam', 13.9578, 107.9655, 'https://picsum.photos/seed/tourism_site_1049/600/400', N'Gia Lai Restaurant Group', 'https://stayhub.vn/di-san/1049', 'Active', GETDATE(), GETDATE()),
(1050, N'Legendary 3-Generation Family Eatery of Gia Lai', 'Restaurant', N'Beloved family-run establishment serving secret heirloom recipes perfected across three generations, popular among locals in Gia Lai.', N'15 Hang Dao Street, Old Quarter Gia Lai', N'Gia Lai', N'Vietnam', 13.9833, 108, 'https://picsum.photos/seed/tourism_site_1050/600/400', N'Gia Lai Food & Beverage Guild', 'https://stayhub.vn/di-san/1050', 'Active', GETDATE(), GETDATE());
