(1051, N'Traditional Spring Folk & Cultural Festival of Gia Lai', 'Activity', N'The largest annual cultural celebration featuring sacred processions, lion dances, and lively traditional folk games in Gia Lai.', N'Central Stadium and Public Square, Gia Lai', N'Gia Lai', N'Vietnam', 14.0088, 108.0345, 'https://picsum.photos/seed/tourism_site_1051/600/400', N'Gia Lai Department of Culture', 'https://stayhub.vn/di-san/1051', 'Active', GETDATE(), GETDATE()),
(1052, N'Rural Cycling & Golden Rice Harvest Experience of Gia Lai', 'Activity', N'Eco-friendly cycling excursion through peaceful rural roads, joining local farmers in rice harvesting activities across Gia Lai.', N'Scenic Countryside Pathways, Gia Lai', N'Gia Lai', N'Vietnam', 14.0343, 108.069, 'https://picsum.photos/seed/tourism_site_1052/600/400', N'Gia Lai Community Tourism Cooperative', 'https://stayhub.vn/di-san/1052', 'Active', GETDATE(), GETDATE()),
(1053, N'Sunset River Rowing & Scenic Boat Tour of Gia Lai', 'Activity', N'Relaxing wooden rowboat journey gliding across tranquil river waters while admiring breathtaking golden sunsets in Gia Lai.', N'Central Tourist Boat Wharf, Gia Lai', N'Gia Lai', N'Vietnam', 13.9098, 107.9535, 'https://picsum.photos/seed/tourism_site_1053/600/400', N'Gia Lai River Boat Management', 'https://stayhub.vn/di-san/1053', 'Inactive', GETDATE(), GETDATE()),
(1054, N'Traditional Handicraft & Ceramic Village of Gia Lai', 'Other', N'Centuries-old artisan community dedicated to molding fine pottery, carving ironwood, and weaving bamboo baskets across Gia Lai.', N'Historic Craft Village, Nghia Hung District, Gia Lai', N'Gia Lai', N'Vietnam', 13.9353, 107.988, 'https://picsum.photos/seed/tourism_site_1054/600/400', N'Gia Lai Handicraft Association', 'https://stayhub.vn/di-san/1054', 'Active', GETDATE(), GETDATE()),
(1055, N'Historic Sanctuary & Temple Complex of Dak Lak', 'Heritage', N'Ancient architectural sanctuary and temple complex deeply connected to the centuries-old history of national defense across Dak Lak.', N'Central Heritage District, Dinh Bang Ward, Dak Lak', N'Dak Lak', N'Vietnam', 12.6442, 108.0725, 'https://picsum.photos/seed/tourism_site_1055/600/400', N'Dak Lak Department of Historical Relics', 'https://stayhub.vn/di-san/1055', 'Active', GETDATE(), GETDATE()),
