INSERT INTO TicketTypes (Id, Name, Description, IsActive, CreatedAt, UpdatedAt) VALUES
(1, N'Standard All-Inclusive Tour Ticket - Adults', N'Comprehensive standard pass for guests aged 12 and above (or over 1.4m height). Covers full sightseeing admission, private transport, and travel insurance coverage throughout the itinerary.', 1, GETDATE(), NULL),
(2, N'Standard All-Inclusive Tour Ticket - Children', N'Discounted admission package for children aged 5 to 11 (height between 1.0m and 1.4m). Includes reserved coach seating, kid-friendly meal options, and amusement park entry.', 1, GETDATE(), NULL),
(3, N'Complimentary Pass - Infants Under 5', N'Free admission pass for infants under 5 years old (height below 1.0m) traveling with parents. Parents are responsible for the infant''s meals and sleeping arrangements.', 1, GETDATE(), NULL),
(4, N'Senior Citizen Concession Pass - 60+ Years', N'Dedicated privilege pass offering priority queue access, gentle dietary meal options, and attentive medical assistance on standby for elderly guests.', 1, GETDATE(), NULL),
(5, N'Student & Youth Discounted Ticket', N'Special concession fare supporting students and youth upon presentation of a valid student ID card. Applicable for educational excursions and outdoor learning programs.', 1, GETDATE(), NULL),
(6, N'Early Bird Saver Combo - Weekday Departure', N'Value combo saving up to 15% on overall tour costs when reservations are finalized at least 30 days prior to departures from Monday to Thursday.', 1, GETDATE(), NULL),
(7, N'Early Bird Saver Combo - Weekend Departure', N'Special advance booking offer for Saturday and Sunday departures, guaranteeing prime hotel room assignments and premium coach seating.', 1, GETDATE(), NULL),
(8, N'Luxury VIP All-Inclusive Service Package', N'The ultimate travel experience featuring private limousine transport, 5-star luxury accommodations, dedicated private English-speaking guides, and fast-track VIP entry.', 1, GETDATE(), NULL),
(9, N'Morning Half-Day Express Tour Pass', N'Concise 4-hour morning itinerary from 8:00 AM to 12:00 PM, covering admission to major historical monuments and round-trip downtown hotel transfers.', 1, GETDATE(), NULL),
(10, N'Afternoon Half-Day Sunset Sightseeing Pass', N'Relaxing afternoon schedule from 1:30 PM to 5:30 PM, exploring city architectural landmarks and watching romantic sunsets at iconic vantage points.', 1, GETDATE(), NULL),
(11, N'After-Dark City & Dinner Cruise Pass', N'Vibrant night sightseeing package including admission to evening cultural performances or river cruises along with a luxury buffet dinner.', 1, GETDATE(), NULL),
(12, N'2-Day 1-Night Short Escape All-Inclusive Ticket', N'Covers modern coach transportation, 1-night accommodation at a 4-star standard hotel, 3 full meals, and entry tickets to all itinerary attractions.', 1, GETDATE(), NULL),
(13, N'3-Day 2-Night Comprehensive Discovery Ticket', N'All-encompassing pass covering all expenses for 3 days of exploration, travel insurance, and a special BBQ Gala Dinner on the second evening.', 1, GETDATE(), NULL),
(14, N'4-Day 3-Night Regional Exploration Ticket', N'Complete multi-day package including round-trip flights or train transport, full-time tour guide services, and regional specialty dining.', 1, GETDATE(), NULL),
(15, N'5-Day 4-Night Grand Heritage Expedition Pass', N'Premium cross-country travel package covering all accommodation, dining, and admission across multiple provinces with zero hidden fees.', 1, GETDATE(), NULL),
(16, N'Small Family Combo - 2 Adults & 1 Child', N'Value package tailored for small families, including complimentary water park entry for the child and a relaxing spa voucher for parents.', 1, GETDATE(), NULL),
(17, N'Large Family Combo - 4 Adults & 2 Children', N'Special bundle for extended families, providing private spacious van transport and interconnected family hotel suites for a cozy gathering.', 1, GETDATE(), NULL),
(18, N'Corporate Team Building Group Package', N'Applicable for groups of 20 or more guests, including customized beach banners, outdoor sound systems for beach games, and professional group photography.', 1, GETDATE(), NULL),
(19, N'Corporate Gala Dinner & Event Package', N'Comprehensive tour package featuring a grand evening Gala Dinner complete with premium seafood menus, professional MC hosting, and entertainment.', 1, GETDATE(), NULL),
(20, N'Private English-Speaking Tour Guide Service', N'Hire an experienced private guide fluent in English with deep historical and cultural expertise, providing personalized commentary and flexible pacing.', 1, GETDATE(), NULL),
(21, N'Private Airport Limousine Round-Trip Transfer', N'Punctual luxury airport pickup and drop-off using executive limousine vans with massage seats, complimentary refreshments, and luggage assistance.', 1, GETDATE(), NULL),
(22, N'Dedicated Chaperone Service for Senior Guests', N'Personalized care package providing wheelchair mobility assistance, health monitoring, and one-on-one companionship for elderly travelers.', 1, GETDATE(), NULL),
(23, N'Local Resident Special Concession Ticket', N'Special 30% discount fare for local residents upon presentation of valid national identity cards, encouraging community exploration.', 1, GETDATE(), NULL),
(24, N'Round-Trip Scenic Cable Car & Summit Pass', N'Includes two-way cable car rides over mountain forests or ocean waters, allowing guests to enjoy breathtaking panoramic aerial views.', 1, GETDATE(), NULL),
(25, N'Hot Spring Onsen & Mineral Spa Day Pass', N'All-access day pass to natural thermal mineral springs, including unlimited outdoor hot tub soaking, steam saunas, and herbal drinks.', 1, GETDATE(), NULL),
(26, N'5-Star Seafood Buffet Lunch Experience Pass', N'Savor over 100 premium fresh seafood items and international Asian-Western specialties at a luxury restaurant with stunning coastal views.', 1, GETDATE(), NULL),
(27, N'Royal Hue Imperial Banquet Dinner Pass', N'Step back in time with a traditional imperial dining experience, wearing royal robes and savoring court delicacies accompanied by live royal music.', 1, GETDATE(), NULL),
(28, N'Scuba Diving & Coral Reef Exploration Pass', N'Includes speedboat transfers, professional international diving equipment, certified one-on-one instructor supervision, and a seafood island lunch.', 1, GETDATE(), NULL),
(29, N'Kayak & Stand-Up Paddleboard Adventure Pass', N'Exciting water sports package covering safety life vests, high-quality kayak/SUP rentals, and basic technical instruction from certified guides.', 1, GETDATE(), NULL),
(30, N'Luxury Glamping Overnight Experience Pass', N'Overnight stay in a spacious Mongolian-style luxury tent with soft bedding, outdoor BBQ steak dinner, campfire gathering, and sunrise coffee.', 1, GETDATE(), NULL),
(31, N'Sunrise Cloud Hunting & Mountain Coffee Pass', N'Early morning excursion departing at 4:30 AM in specialized 4WD vehicles to prime cloud-hunting spots, including hot breakfast and coffee above the clouds.', 1, GETDATE(), NULL),
(32, N'National Museum & Heritage All-Access Pass', N'Convenient multi-entry pass granting fast-track admission to major historical museums, art galleries, and cultural monuments across the city.', 1, GETDATE(), NULL),
(33, N'Theme Park & Thrill Ride Unlimited Day Pass', N'Unlimited full-day access to all roller coasters, water park attractions, and spectacular real-scene cultural shows inside the resort complex.', 1, GETDATE(), NULL),
(34, N'Saigon River Sunset Dinner Cruise Ticket', N'Three-hour evening cruise along the Saigon River aboard a modern 3-deck vessel, enjoying illuminated city skylines and a lavish buffet dinner.', 1, GETDATE(), NULL),
(35, N'Traditional Vietnamese Cooking Class & Market Tour', N'Join a master chef to visit local morning markets, select fresh ingredients, and prepare four classic Vietnamese dishes at an interactive kitchen setup.', 1, GETDATE(), NULL),
(36, N'Eco-Cycling Village & Forest Trail Day Pass', N'Includes high-quality mountain bikes, helmets, unlimited bottled water, picnic lunch, and guide supervision along tranquil countryside trails.', 1, GETDATE(), NULL),
(37, N'Old Quarter Walking & Street Food Tasting Tour', N'Guided culinary walking excursion visiting six historic family-run eateries to sample authentic street food delicacies and egg coffee.', 1, GETDATE(), NULL),
(38, N'Traditional Pottery Making Workshop Pass', N'Visit a historic ceramic workshop, learn wheel-throwing techniques directly from master potters, and take home your fired clay creation.', 1, GETDATE(), NULL),
(39, N'Silk Weaving & Artisan Workshop Experience', N'Discover the millennium-old process of silkworm cultivation and thread spinning, try hand-weaving on a wooden loom, and receive a silk scarf gift.', 1, GETDATE(), NULL),
(40, N'French Colonial Villa Stay & Heritage Tour Combo', N'2-day 1-night getaway staying at an elegantly restored colonial villa, including royal afternoon tea and a guided architectural walking tour.', 1, GETDATE(), NULL),
(41, N'Last-Minute 48-Hour Special Discount Ticket', N'Maximizes savings for travelers booking within 48 hours of departure while maintaining 100% full package benefits and top-tier service quality.', 1, GETDATE(), NULL),
(42, N'Silver Pass Loyalty Member Tier Ticket', N'Member privilege ticket granting a 5% discount across all tours, priority early hotel check-in upon arrival, and reward points accumulation.', 1, GETDATE(), NULL),
(43, N'Gold Pass Loyalty Member Tier Ticket', N'Exclusive Gold member ticket offering a 10% discount, complimentary room category upgrades subject to availability, and private check-in counters.', 1, GETDATE(), NULL),
(44, N'Platinum Pass Lifetime VIP Tier Ticket', N'Top-tier membership pass featuring a 15% lifetime discount, complimentary private airport limousine transfers, and birthday wine bottles.', 0, GETDATE(), NULL),
(45, N'Northwest Autumn Golden Terraced Rice Tour Pass', N'Seasonal package designed for September and October harvests, visiting the most spectacular golden terraced slopes in Hoang Su Phi and Mu Cang Chai.', 1, GETDATE(), NULL),
(46, N'Dong Van Karst Buckwheat Flower Season Pass', N'November floral tour exploring limestone canyons, featuring complimentary ethnic minority dress photography and visits to weekend mountain markets.', 1, GETDATE(), NULL),
(47, N'Mountain Town Cherry Blossom Festival Pass', N'January spring tour visiting Da Lat''s most brilliant pink cherry blossom avenues, paired with hot herbal tea by Xuan Huong Lake.', 1, GETDATE(), NULL),
(48, N'Hoi An Full Moon Lantern Festival Tour Pass', N'Special evening pass for the monthly full moon celebration, covering wooden boat rides on the Hoai River, floating paper lanterns, and dinner.', 1, GETDATE(), NULL),
(49, N'Mekong Delta Flood Season Discovery Pass', N'August to November seasonal excursion exploring green duckweed carpets in Tra Su forest, picking sesbania flowers, and tasting river specialties.', 1, GETDATE(), NULL),
(50, N'Highland Community Charity & Cultural Exchange Pass', N'Covers transport, accommodation, and educational supply donations for rural mountain children, followed by an evening campfire musical gathering.', 1, GETDATE(), NULL);
